const item = $input.first().json;
const data = item.body?.data || item.data || {};
const key = data.key || {};
const remoteJid = key.remoteJid || '';
const telefone = remoteJid.replace(/@.*$/, '');
const rawMsg = data.message?.conversation 
  || data.message?.extendedTextMessage?.text 
  || '';
const cleanMsg = rawMsg.trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const staticData = $getWorkflowStaticData('global');
const attendedContacts = staticData.attendedContacts || {};
const menuBannerSent = staticData.menuBannerSent || {};
const purchaseStates = staticData.purchaseStates || {};

if (!remoteJid) { return []; }

if (cleanMsg === 'finalizar') {
  delete attendedContacts[remoteJid];
  delete menuBannerSent[telefone];
  delete purchaseStates[remoteJid];
  staticData.attendedContacts = attendedContacts;
  staticData.menuBannerSent = menuBannerSent;
  staticData.purchaseStates = purchaseStates;
  return [{ json: { telefone, nomeCliente: data.pushName || 'Cliente', mensagemRecebida: rawMsg, routeIndex: 5 } }];
}

if (attendedContacts[remoteJid] || key.fromMe === true) { return []; }
if (remoteJid.includes('@g.us') || remoteJid.includes('status@broadcast')) { return []; }

if (cleanMsg === 'menu') {
  delete purchaseStates[remoteJid];
  staticData.purchaseStates = purchaseStates;
}

const currentPurchase = purchaseStates[remoteJid];
let routeIndex = 6;
let planoSelecionado = '';
let formaPagamento = '';

if (currentPurchase?.stage === 'awaiting_plan') {
  const plans = { '1': 'Plano Diário (24h) - R$ 2,00', '2': 'Plano 14 Dias - R$ 15,00', '3': 'Plano Solteiro (Mensal) - R$ 25,00', '4': 'Plano Família (Mensal) - R$ 30,00' };
  planoSelecionado = plans[cleanMsg] || "";
  if (planoSelecionado) {
    purchaseStates[remoteJid] = { stage: 'awaiting_payment', plan: planoSelecionado };
    staticData.purchaseStates = purchaseStates;
    routeIndex = 7;
  } else { routeIndex = 10; }
} else if (currentPurchase?.stage === 'awaiting_payment') {
  const payments = { '1': 'PIX', 'pix': 'PIX', '2': 'Cartão', 'cartao': 'Cartão', '3': 'Boleto', 'boleto': 'Boleto' };
  formaPagamento = payments[cleanMsg] || "";
  if (formaPagamento) {
    planoSelecionado = currentPurchase.plan;
    delete purchaseStates[remoteJid];
    attendedContacts[remoteJid] = true;
    staticData.purchaseStates = purchaseStates;
    staticData.attendedContacts = attendedContacts;
    routeIndex = 8;
  } else { routeIndex = 9; }
} else if (cleanMsg === '1' || cleanMsg.includes('plano') || cleanMsg.includes('preco')) {
  purchaseStates[remoteJid] = { stage: 'awaiting_plan' };
  staticData.purchaseStates = purchaseStates;
  routeIndex = 0;
} else if (cleanMsg === '3' || cleanMsg.includes('suporte') || cleanMsg.includes('ajuda') || cleanMsg.includes('defeito') || cleanMsg.includes('instala')) {
  routeIndex = 1;
} else if (cleanMsg === '2' || cleanMsg.includes('teste') || cleanMsg.includes('gratis')) {
  routeIndex = 2;
} else if (cleanMsg === '5' || cleanMsg.includes('atendente') || cleanMsg.includes('humano') || cleanMsg.includes('falar')) {
  routeIndex = 3;
}

if (routeIndex === 6 && !menuBannerSent[telefone]) {
  menuBannerSent[telefone] = true;
  staticData.menuBannerSent = menuBannerSent;
  routeIndex = 4;
}

return [{
  json: {
    telefone,
    nomeCliente: data.pushName || 'Cliente',
    mensagemRecebida: rawMsg,
    routeIndex: routeIndex,
    planoSelecionado: planoSelecionado,
    formaPagamento: formaPagamento
  }
}];

